          "find": "class UnitNormItemEmbedding(nn.Embedding):
    def forward(self, indices: torch.Tensor) -> torch.Tensor:
        embeddings = super().forward(indices)
        embeddings = torch.nn.functional.normalize(embeddings, p=2, dim=-1, eps=1e-12)
        return embeddings.masked_fill(indices.eq(0).unsqueeze(-1), 0.0)",
          "replace": "class UnitNormItemEmbedding(nn.Embedding):
    def __init__(self, num_embeddings: int, embedding_dim: int,
                 padding_idx: int = 0, rank: int = 64):
        super().__init__(num_embeddings, rank, padding_idx=padding_idx)
        self.projection = nn.Parameter(torch.empty(rank, embedding_dim))
        nn.init.xavier_uniform_(self.projection)

    def forward(self, indices: torch.Tensor) -> torch.Tensor:
        embeddings = torch.matmul(super().forward(indices), self.projection)
        embeddings = torch.nn.functional.normalize(embeddings, p=2, dim=-1, eps=1e-12)
        return embeddings.masked_fill(indices.eq(0).unsqueeze(-1), 0.0)"
